"""Données de marché et qualité : prix ajustés, OHLC, fréquences, valeurs aberrantes, alignement, sources."""
from __future__ import annotations

from patrick.knowledge.dictionary import d

T = "donnees"
TERMS = [
    d(T, "cours_cloture_ajuste", "Cours de clôture", "Closing price", 1,
      "Dernier prix de la séance (souvent issu de l'enchère de clôture). C'est la série la plus utilisée, mais son choix n'est pas neutre : la clôture d'un marché lointain est observée à un autre instant que celle d'un marché proche.",
      "Last price of the session (often from the closing auction). It is the most used series, but choosing it is not neutral: the close of a distant market is observed at a different moment from that of a nearby one.",
      see="ohlc enchere_ouverture_cloture"),
    d(T, "cours_ajuste", "Cours ajusté", "Adjusted price", 1,
      "Historique de cours corrigé des splits et des dividendes pour que chaque variation reflète le vrai rendement de l'actionnaire. Sans ajustement, un dividende ou un split apparaît comme une chute fictive.",
      "Price history corrected for splits and dividends so that each change reflects the shareholder's true return. Without adjustment, a dividend or split shows up as a fictitious drop.",
      see="split_regroupement dividende rendement"),
    d(T, "ohlc", "OHLC (ouverture, haut, bas, clôture)", "OHLC (open, high, low, close)", 1,
      "Les quatre prix qui résument une période : ouverture, plus haut, plus bas, clôture. Le haut et le bas donnent une mesure de volatilité bien plus précise que la seule clôture (Parkinson, Garman-Klass).",
      "The four prices summarising a period: open, high, low, close. The high and low give a much more precise volatility measure than the close alone (Parkinson, Garman-Klass).",
      see="variance_parkinson variance_garman_klass candlestick", alias="OHLCV; bougie"),
    d(T, "candlestick", "Bougie japonaise", "Candlestick", 1,
      "Représentation graphique d'une période : un corps entre ouverture et clôture, des mèches jusqu'au plus haut et au plus bas, colorée selon que la clôture est au-dessus ou au-dessous de l'ouverture.",
      "Graphical representation of a period: a body between open and close, wicks up to the high and down to the low, coloured by whether the close is above or below the open.",
      see="ohlc"),
    d(T, "volume_echange", "Volume échangé", "Traded volume", 1,
      "Nombre de titres (ou montant) échangés sur une période. Un mouvement de prix accompagné d'un fort volume est jugé plus crédible ; le volume sert aussi à mesurer la liquidité d'un titre.",
      "Number of securities (or amount) traded over a period. A price move with heavy volume is judged more credible; volume also measures a security's liquidity.",
      see="liquidite illiquidite_amihud"),
    d(T, "frequence_donnees", "Fréquence des données", "Data frequency", 1,
      "Intervalle entre deux observations : tick (chaque transaction), minute, jour, semaine, mois. Plus elle est fine, plus il y a de données mais plus le bruit de microstructure est important ; les séries macroéconomiques sont mensuelles ou trimestrielles.",
      "Interval between two observations: tick (each trade), minute, day, week, month. The finer it is, the more data but the more microstructure noise; macroeconomic series are monthly or quarterly.",
      see="bruit_de_microstructure fuseau_horaire"),
    d(T, "donnees_tick", "Données tick et intrajournalières", "Tick and intraday data", 3,
      "Chaque transaction ou chaque changement du carnet, horodaté à la milliseconde. Elles permettent de mesurer la variance réalisée avec précision mais sont lourdes, coûteuses, et sujettes à des artefacts (annulations, erreurs, rebonds bid-ask).",
      "Every trade or order-book change, timestamped to the millisecond. They allow precise realised variance but are heavy, costly and prone to artefacts (cancellations, errors, bid-ask bounce).",
      see="variance_realisee bruit_de_microstructure"),
    d(T, "valeurs_manquantes", "Valeurs manquantes", "Missing values", 1,
      "Observations absentes (jour férié, titre non coté, panne de source). Les remplir par la dernière valeur connue crée des rendements nuls fictifs ; les supprimer décale les calendriers. Le choix doit être explicite et testé.",
      "Absent observations (holiday, unlisted security, source outage). Filling with the last known value creates fictitious zero returns; dropping them shifts calendars. The choice should be explicit and tested.",
      see="frozen_prices alignement_temporel"),
    d(T, "valeur_aberrante", "Valeur aberrante (outlier)", "Outlier", 2,
      "Observation très éloignée des autres : vraie (krach) ou erronée (virgule décalée). Les retirer sans examen supprime les événements les plus informatifs ; les garder sans examen peut fausser une moyenne ou une régression.",
      "Observation far from the others: genuine (crash) or erroneous (shifted decimal). Dropping them unexamined removes the most informative events; keeping them unexamined can distort a mean or regression.",
      see="aberrant_return winsorisation"),
    d(T, "winsorisation", "Winsorisation", "Winsorisation", 2,
      "Écrêtage des valeurs extrêmes à un percentile (par exemple 1 % et 99 %) au lieu de les supprimer. Elle réduit l'influence des aberrations sur les moyennes et régressions tout en gardant l'observation dans l'échantillon.",
      "Clipping extreme values to a percentile (for example 1% and 99%) instead of removing them. It cuts the influence of outliers on means and regressions while keeping the observation in the sample.",
      see="valeur_aberrante"),
    d(T, "alignement_temporel", "Alignement temporel", "Time alignment", 2,
      "Mettre plusieurs séries sur les mêmes dates avant de calculer des corrélations ou des rendements. On aligne les niveaux sur les dates communes, puis on calcule les rendements : l'inverse mélange des intervalles différents et fausse les liens.",
      "Putting several series on the same dates before computing correlations or returns. Levels are aligned on common dates, then returns computed: the reverse mixes different intervals and distorts links.",
      see="alignment fuseau_horaire valeurs_manquantes"),
    d(T, "point_in_time", "Données à la date de publication (point-in-time)", "Point-in-time data", 3,
      "Données telles qu'elles étaient connues à une date passée, avec leurs révisions ultérieures exclues. Indispensables en backtest : utiliser la valeur révisée d'un chiffre qu'on ne connaissait pas encore à l'époque crée une fuite d'information.",
      "Data as they were known at a past date, with later revisions excluded. Essential in backtesting: using the revised value of a figure not yet known at the time creates a look-ahead leak.",
      see="vintage alfred biais_look_ahead", alias="PIT"),
    d(T, "biais_survivant_donnees", "Biais du survivant dans les données", "Survivorship bias in data", 3,
      "Une base qui ne contient que les entreprises encore cotées aujourd'hui oublie celles qui ont fait faillite ou été rachetées : les rendements historiques sont trop beaux. Il faut des univers « datés » qui incluent les disparus.",
      "A database containing only companies still listed today forgets those that went bankrupt or were acquired: historical returns look too good. One needs dated universes that include the delisted.",
      see="biais_survivant"),
    d(T, "fred_source", "FRED (Federal Reserve Economic Data)", "FRED (Federal Reserve Economic Data)", 2,
      "Base publique de la Fed de Saint-Louis regroupant des centaines de milliers de séries macro-financières (inflation, emploi, taux, écarts de crédit). Gratuite, mais la plupart des séries sont révisées après publication : voir ALFRED pour les valeurs d'époque.",
      "Public database of the St. Louis Fed collecting hundreds of thousands of macro-financial series (inflation, jobs, rates, credit spreads). Free, but most series are revised after release: see ALFRED for as-first-published values.",
      see="alfred vintage"),
    d(T, "yahoo_source", "Données Yahoo Finance", "Yahoo Finance data", 1,
      "Source gratuite et large de cours historiques (actions, indices, devises, futures, crypto). Pratique mais non contractuelle : erreurs ponctuelles, ajustements parfois discutables, historique et heures de publication à vérifier.",
      "Free and broad source of historical prices (stocks, indices, currencies, futures, crypto). Convenient but non-contractual: occasional errors, sometimes questionable adjustments, history and release times to check.",
      see="cours_ajuste data_freshness"),
    d(T, "donnees_alternatives", "Données alternatives", "Alternative data", 3,
      "Informations hors des sources financières classiques : images satellites, transactions par carte, trafic web, textes de presse, géolocalisation. Elles peuvent devancer les chiffres officiels mais sont chères, bruitées et vite arbitrées.",
      "Information outside classic financial sources: satellite images, card transactions, web traffic, press text, geolocation. They can precede official figures but are expensive, noisy and quickly arbitraged away.",
      see="news_sentiment decroissance_alpha"),
    d(T, "latence_publication", "Délai de publication", "Publication lag", 2,
      "Temps entre la période mesurée et la date où le chiffre devient public (l'emploi du mois m sort début m+1, le PIB d'un trimestre plusieurs semaines après). Un modèle ne doit utiliser une donnée qu'après cette date.",
      "Time between the period measured and the date the figure becomes public (month-m jobs come out early m+1, a quarter's GDP weeks later). A model must only use a figure after that date.",
      see="publication_lag point_in_time"),
    d(T, "base_rebasee", "Série rebasée (indice base 100)", "Rebased series (index base 100)", 1,
      "Série ramenée à 100 à une date de départ pour comparer des actifs de niveaux différents. Attention : un niveau « rebasé » change si la date de départ change, ce qui peut faire croire à des relations qui n'existent pas.",
      "Series scaled to 100 at a start date to compare assets of different levels. Beware: a 'rebased' level changes if the start date changes, which can suggest relationships that do not exist.",
      see="alignement_temporel"),
    d(T, "saisonnalite_donnees", "Saisonnalité et désaisonnalisation (CVS)", "Seasonality and seasonal adjustment", 2,
      "Régularités de calendrier (ventes de décembre, chômage d'été). Les séries « corrigées des variations saisonnières » les retirent pour montrer la tendance ; elles sont recalculées à chaque publication, donc révisées.",
      "Calendar regularities (December sales, summer unemployment). 'Seasonally adjusted' series remove them to show the trend; they are recomputed at each release, hence revised.",
      see="revision_donnees sarima"),
    d(T, "revision_donnees", "Révision des données", "Data revision", 2,
      "Les statistiques économiques sont corrigées après leur première publication, parfois fortement (PIB, emploi). Un backtest qui utilise la valeur finale plutôt que la première triche sur ce qu'on savait.",
      "Economic statistics are corrected after first release, sometimes heavily (GDP, jobs). A backtest using the final value rather than the first cheats about what was known.",
      see="revision_vs_move vintage point_in_time"),
    d(T, "bruit_de_microstructure", "Bruit de microstructure", "Microstructure noise", 3,
      "Écarts entre le prix observé et la « vraie » valeur dus aux frictions : rebond entre bid et ask, pas de cotation, délais. Il gonfle la variance mesurée aux très hautes fréquences, d'où les échelles de 5 minutes et les estimateurs robustes.",
      "Gaps between the observed price and the 'true' value due to frictions: bounce between bid and ask, tick size, delays. It inflates measured variance at very high frequencies, hence 5-minute sampling and robust estimators.",
      see="donnees_tick variance_realisee"),
    d(T, "gap_overnight", "Écart de nuit (gap overnight)", "Overnight gap", 2,
      "Différence entre la clôture de la veille et l'ouverture du jour : elle concentre les nouvelles tombées marché fermé (résultats, décisions de banque centrale). Les mesures fondées sur haut-bas l'ignorent, d'où leur biais à la baisse.",
      "Difference between the previous close and today's open: it concentrates news arriving while the market is closed (earnings, central-bank decisions). High-low based measures ignore it, hence their downward bias.",
      see="ohlc variance_parkinson"),
    d(T, "decimales_precision", "Précision numérique des prix", "Price precision", 2,
      "Les prix et rendements sont stockés en nombres à virgule flottante : de très petites différences d'arrondi existent et rendent fragile toute comparaison d'égalité exacte entre deux calculs ou deux machines.",
      "Prices and returns are stored as floating-point numbers: tiny rounding differences exist and make any exact-equality comparison between two computations or machines fragile.",
      see="rendement"),
]
